const LESSON_STATUSES=["proposed","accepted","learned","verified","reviewed","archived"];
function profileId(env){return "owner:"+(env.MELITURGOS_USER||"default")}
async function learningProfile(req,env){const id=profileId(env);if(req.method==="GET"){const p=await env.DB.prepare("SELECT id,owner,level,preferences,goals,domains,created_at,updated_at,active FROM learning_profiles WHERE id=?").bind(id).first();return json({profile:p||{id,owner:env.OWNER_NAME||"Adrien",level:"unspecified",preferences:{},goals:[],domains:[],active:1}})}const b=await readJson(req),level=String(b.level||"unspecified").slice(0,80),prefs=b.preferences&&typeof b.preferences==="object"?b.preferences:{},goals=Array.isArray(b.goals)?b.goals.slice(0,30).map(String):[],domains=Array.isArray(b.domains)?b.domains.slice(0,30).map(String):[];if(secret(JSON.stringify({level,prefs,goals,domains})))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const now=Date.now();await env.DB.prepare("INSERT INTO learning_profiles(id,owner,level,preferences,goals,domains,created_at,updated_at,active) VALUES(?,?,?,?,?,?,?,?,1) ON CONFLICT(id) DO UPDATE SET level=excluded.level,preferences=excluded.preferences,goals=excluded.goals,domains=excluded.domains,updated_at=excluded.updated_at,active=1").bind(id,env.OWNER_NAME||"Adrien",level,JSON.stringify(prefs),JSON.stringify(goals),JSON.stringify(domains),now,now).run();audit("learning_profile_updated",req,{profile_id:id});return json({ok:true,profile_id:id,level,goals,domains})}
async function learningProgress(env){const id=profileId(env),[p,t,r,l]=await Promise.all([env.DB.prepare("SELECT id,owner,level,preferences,goals,domains,updated_at FROM learning_profiles WHERE id=?").bind(id).first(),env.DB.prepare("SELECT id,topic,mastery,confidence,attempts,errors,last_reviewed,next_review,status FROM learning_topics WHERE profile_id=? AND status='active' ORDER BY mastery ASC,topic").bind(id).all(),env.DB.prepare("SELECT id,session_id,turn_id,lesson,learning_status,proposal_reason,validated,understanding_status,importance,confidence,created_at,last_used_at,provenance,correction_turn_id,retest_id,memory_id FROM professor_lessons ORDER BY id DESC LIMIT 50").all(),env.DB.prepare("SELECT id,lesson_id,topic_id,scheduled_at,status,score,created_at FROM learning_reviews WHERE profile_id=? ORDER BY scheduled_at").bind(id).all()]);const lessons=(l.results||[]).map(x=>({...x,status:x.learning_status||x.understanding_status||"pending_retest",understood:x.understanding_status==="understood"}));return json({profile:p||null,topics:t.results||[],lessons,reviews:r.results||[],due_reviews:(r.results||[]).filter(x=>x.status==="scheduled"&&x.scheduled_at<=Date.now()),summary:{lessons:lessons.length,understood_lessons:lessons.filter(x=>x.understood).length,pending_retests:lessons.filter(x=>!x.understood).length}})}
async function learningTopic(req,env){const b=await readJson(req),topic=String(b.topic||"").trim().slice(0,160);if(!topic)throw new ClientError("Sujet requis.","TOPIC_REQUIRED");if(secret(topic))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const id=profileId(env),mastery=Math.max(0,Math.min(1,Number(b.mastery)||0)),confidence=Math.max(0,Math.min(1,Number(b.confidence)||.5)),attempts=Math.max(0,Number(b.attempts)||0),errors=Math.max(0,Number(b.errors)||0),next=Number(b.next_review)||null;await env.DB.prepare("INSERT INTO learning_topics(profile_id,topic,mastery,confidence,attempts,errors,last_reviewed,next_review,status) VALUES(?,?,?,?,?,?,?,?,?)").bind(id,topic,mastery,confidence,attempts,errors,Date.now(),next,"active").run();return json({ok:true,topic,mastery,confidence,next_review:next})}
async function learningReview(req,env){const b=await readJson(req),when=Number(b.scheduled_at);if(!Number.isFinite(when)||when< Date.now())throw new ClientError("scheduled_at futur requis.","REVIEW_DATE_INVALID");const id=profileId(env);await env.DB.prepare("INSERT INTO learning_reviews(profile_id,lesson_id,topic_id,scheduled_at,status,score,notes,created_at) VALUES(?,?,?,?,?,?,?,?)").bind(id,Number(b.lesson_id)||null,Number(b.topic_id)||null,when,"scheduled",null,String(b.notes||"").slice(0,500),Date.now()).run();return json({ok:true,status:"scheduled",scheduled_at:when})}
async function learningLessonStatus(req,env,id){const b=await readJson(req),status=String(b.status||"");if(!LESSON_STATUSES.includes(status))throw new ClientError("Statut de leçon invalide.","LESSON_STATUS_INVALID");const reason=String(b.reason||"").slice(0,500);if(secret(reason))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const r=await env.DB.prepare("UPDATE professor_lessons SET learning_status=?,proposal_reason=? WHERE id=?").bind(status,reason,id).run();if(!r.meta||r.meta.changes!==1)throw new ClientError("Leçon introuvable.","LESSON_NOT_FOUND",404);return json({ok:true,lesson_id:id,status,reason})}
