async function professorSession(req,env){const b=await readJson(req),goal=String(b&&b.goal||"");if(secret(goal))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const id=crypto.randomUUID(),now=Date.now();await env.DB.prepare("INSERT INTO professor_sessions(id,created_at,updated_at,last_used_at,status,goal,provenance) VALUES(?,?,?,?,?,?,?)").bind(id,now,now,now,"active",goal.slice(0,2000),"professor_session").run();return json({ok:true,session_id:id,status:"active",stage:"session",next_action:"question"})}
async function professorGet(env,id){const s=await env.DB.prepare("SELECT id,created_at,updated_at,last_used_at,status,goal,provenance FROM professor_sessions WHERE id=?").bind(id).first();if(!s)throw new ClientError("Session professeur introuvable.","PROFESSOR_SESSION_NOT_FOUND",404);const [t,l]=await Promise.all([env.DB.prepare("SELECT id,session_id,created_at,last_used_at,kind,question,answer,confidence,memories_json,tools_json,critique,correction,improved_answer,correction_id,retest_id,passed,explanation_variant,provenance FROM professor_turns WHERE session_id=? ORDER BY id").bind(id).all(),env.DB.prepare("SELECT id,session_id,turn_id,created_at,last_used_at,lesson,rationale,validated,understanding_status,importance,confidence,memory_id,correction_turn_id,retest_id,provenance FROM professor_lessons WHERE session_id=? ORDER BY id").bind(id).all()]);const turns=t.results||[],lessons=l.results||[];return json({session:s,turns,lessons,summary:{turns:turns.length,questions:turns.filter(x=>x.kind==="question").length,retests:turns.filter(x=>x.kind==="retest").length,understood_lessons:lessons.filter(x=>x.understanding_status==="understood").length,pending_lessons:lessons.filter(x=>x.understanding_status!=="understood").length}})}
async function professorAsk(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),question=profInput(b&&b.question,"question"),s=await env.DB.prepare("SELECT id FROM professor_sessions WHERE id=? AND status='active'").bind(sid).first();if(!s)throw new ClientError("Session professeur introuvable ou terminée.","PROFESSOR_SESSION_NOT_ACTIVE",404);const used=await toolContext(env,question),confidence=used.search_memories.length?0.72:0.48,specialist=specialistForTask(classifyTask(question),question),selectedSpecialist=specialist.available?specialist.id:"general_model",inference=await askAI(env,b&&b.model,[{role:"system",content:systemPrompt(env.OWNER_NAME||"Adrien",used)+"\nMode Professeur piloté par ChatGPT Work. Réponds clairement et reste honnête."},{role:"user",content:question}]),answer=inference.text,now=Date.now(),r=await env.DB.prepare("INSERT INTO professor_turns(session_id,created_at,last_used_at,kind,question,answer,confidence,memories_json,tools_json,provenance,correction_id,retest_id,passed,explanation_variant) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(sid,now,now,"question",question,answer,confidence,JSON.stringify(used.search_memories),JSON.stringify({...used,model_execution:inference,specialist:selectedSpecialist}),"professor_question",null,null,null,0).run();await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(now,now,sid).run();return json({ok:true,session_id:sid,turn_id:r.meta&&r.meta.last_row_id||null,stage:"answer",next_action:"correction",answer,confidence,model:inference.model,fallback_used:inference.fallback_used,tool_succeeded:inference.tool_succeeded,memories:used.search_memories,tools:used,sources:used.sources_used||[],provenance:"professor_question",specialist:selectedSpecialist,specialist_candidate:specialist.id})}
async function professorCorrect(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),tid=Number(b&&b.turn_id),critique=String(b&&b.critique||""),correction=String(b&&b.correction||""),improved=String(b&&b.improved_answer||"");if(!Number.isInteger(tid)||tid<=0)throw new ClientError("turn_id invalide.","PROFESSOR_TURN_INVALID");if(secret(critique)||secret(correction)||secret(improved))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");if(!critique.trim()&&!correction.trim()&&!improved.trim())throw new ClientError("Une critique, correction ou meilleure réponse est requise.","PROFESSOR_CORRECTION_REQUIRED");const session=await env.DB.prepare("SELECT id FROM professor_sessions WHERE id=? AND status='active'").bind(sid).first();if(!session)throw new ClientError("Session professeur introuvable ou terminée.","PROFESSOR_SESSION_NOT_ACTIVE",404);const r=await env.DB.prepare("UPDATE professor_turns SET critique=?,correction=?,improved_answer=?,last_used_at=?,correction_id=? WHERE id=? AND session_id=? AND kind='question'").bind(critique.trim()||null,correction.trim()||null,improved.trim()||null,Date.now(),tid,tid,sid).run();if(!r.meta||r.meta.changes!==1)throw new ClientError("Tour professeur introuvable.","PROFESSOR_TURN_NOT_FOUND",404);await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(Date.now(),Date.now(),sid).run();return json({ok:true,session_id:sid,turn_id:tid,stage:"correction",next_action:"lesson",corrected:true})}
async function professorLesson(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),tid=Number(b&&b.turn_id),lesson=profInput(b&&b.lesson,"lesson"),rationale=String(b&&b.rationale||"");if(!Number.isInteger(tid)||tid<=0)throw new ClientError("turn_id invalide.","PROFESSOR_TURN_INVALID");if(secret(rationale)||secret(lesson))throw new ClientError("Les secrets ne sont jamais acceptés.","SECRET_REJECTED");const t=await env.DB.prepare("SELECT id,critique,correction,improved_answer FROM professor_turns WHERE id=? AND session_id=? AND kind='question'").bind(tid,sid).first();if(!t)throw new ClientError("Tour professeur introuvable.","PROFESSOR_TURN_NOT_FOUND",404);if(!t.critique&&!t.correction&&!t.improved_answer)throw new ClientError("Une correction est requise avant la leçon.","PROFESSOR_CORRECTION_REQUIRED");const duplicate=await env.DB.prepare("SELECT id,memory_id,understanding_status FROM professor_lessons WHERE session_id=? AND turn_id=? AND lesson=?").bind(sid,tid,lesson).first();if(duplicate){const duplicateMemory=Number(duplicate.memory_id)||null;return json({ok:true,session_id:sid,lesson_id:duplicate.id,memory_id:duplicateMemory,duplicate:true,validated:duplicateMemory!==null,understanding_status:duplicate.understanding_status,stage:"lesson",next_action:"retest"})}const now=Date.now(),written=await env.DB.prepare("INSERT INTO professor_lessons(session_id,turn_id,created_at,lesson,rationale,validated,importance,confidence,last_used_at,provenance,correction_turn_id,retest_id,understanding_status,memory_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,NULL)").bind(sid,tid,now,lesson,rationale,1,1,.75,null,"professor_session_lesson",tid,null,"pending_retest").run(),lessonId=Number(written&&written.meta&&written.meta.last_row_id)||null;if(!lessonId)throw new ClientError("Leçon créée sans identifiant.","PROFESSOR_LESSON_ID_MISSING",500);const memory=await addMemory(env,lesson,"lesson",1,"professor_lesson",{provenance:"professor_lesson",professor_session_id:sid,professor_lesson_id:lessonId,professor_turn_id:tid}),memoryId=Number(memory&&memory.id)||null;if(!Number.isInteger(memoryId)||memoryId<=0)throw new ClientError("La leçon n’a pas été mémorisée : memory_id invalide.","PROFESSOR_MEMORY_ID_MISSING",500);await env.DB.prepare("UPDATE professor_lessons SET last_used_at=?,memory_id=? WHERE id=? AND session_id=?").bind(now,memoryId,lessonId,sid).run();await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(now,now,sid).run();return json({ok:true,session_id:sid,lesson_id:lessonId,memory_id:memoryId,duplicate:false,validated:true,understanding_status:"pending_retest",stage:"lesson",next_action:"retest"})}
async function professorRetest(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),question=profInput(b&&b.question||"Réponds à nouveau en appliquant la leçon.","question"),passed=b&&b.passed===true,s=await env.DB.prepare("SELECT id FROM professor_sessions WHERE id=? AND status='active'").bind(sid).first();if(!s)throw new ClientError("Session professeur introuvable ou terminée.","PROFESSOR_SESSION_NOT_ACTIVE",404);const pending=(await env.DB.prepare("SELECT id,lesson,turn_id,confidence FROM professor_lessons WHERE session_id=? AND understanding_status IN ('pending_retest','retry_required') ORDER BY id DESC LIMIT 1").bind(sid).all()).results||[];const lesson=pending[0];if(!lesson)throw new ClientError("Aucune leçon en attente de retest pour cette session.","PROFESSOR_LESSON_PENDING_REQUIRED",409);const used=await toolContext(env,question),variant=passed?0:1,system=systemPrompt(env.OWNER_NAME||"Adrien",used)+(passed?"\nVérifie la compréhension de la leçon validée.":"\nLe retest a échoué. Donne une explication différente, concrète et plus simple; termine par une nouvelle question de retest."),inference=await askAI(env,b&&b.model,[{role:"system",content:system+"\nLeçon à vérifier:\n"+lesson.lesson},{role:"user",content:question}]),answer=inference.text,now=Date.now(),r=await env.DB.prepare("INSERT INTO professor_turns(session_id,created_at,last_used_at,kind,question,answer,confidence,memories_json,tools_json,provenance,correction_id,retest_id,passed,explanation_variant) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(sid,now,now,"retest",question,answer,passed?.88:.4,JSON.stringify(used.search_memories),JSON.stringify({...used,model_execution:inference}),"professor_retest",lesson.turn_id,null,passed?1:0,variant).run(),retestId=r.meta&&r.meta.last_row_id||null;await env.DB.prepare("UPDATE professor_turns SET retest_id=? WHERE id=?").bind(retestId,lesson.turn_id).run();let memoryId=null;if(passed){const mem=await addMemory(env,lesson.lesson,"lesson",1,"professor_retest",{provenance:"professor_retest_passed",professor_session_id:sid,professor_lesson_id:lesson.id,professor_turn_id:lesson.turn_id,retest_id:retestId});memoryId=mem.id;await env.DB.prepare("UPDATE professor_lessons SET validated=1,understanding_status='understood',confidence=?,last_used_at=?,retest_id=?,memory_id=? WHERE id=? AND session_id=?").bind(.88,now,retestId,memoryId,lesson.id,sid).run()}else await env.DB.prepare("UPDATE professor_lessons SET validated=1,understanding_status='retry_required',confidence=?,last_used_at=?,retest_id=? WHERE id=? AND session_id=?").bind(.4,now,retestId,lesson.id,sid).run();await env.DB.prepare("UPDATE professor_sessions SET updated_at=?,last_used_at=? WHERE id=?").bind(now,now,sid).run();return json({ok:true,session_id:sid,turn_id:retestId,lesson_id:lesson.id,answer,confidence:passed?.88:.4,passed,understood:passed,understanding_status:passed?"understood":"retry_required",next_action:passed?"new_question":"new_retest_with_different_explanation",explanation_variant:variant,memory_id:memoryId,model:inference.model,fallback_used:inference.fallback_used,tool_succeeded:inference.tool_succeeded,memories:used.search_memories,tools:used,sources:used.sources_used||[],lessons:[lesson]})}
async function professorClose(req,env){const b=await readJson(req),sid=profInput(b&&b.session_id,"session_id"),now=Date.now(),r=await env.DB.prepare("UPDATE professor_sessions SET status='closed',updated_at=?,last_used_at=? WHERE id=? AND status='active'").bind(now,now,sid).run();if(!r.meta||r.meta.changes!==1)throw new ClientError("Session professeur introuvable ou déjà fermée.","PROFESSOR_SESSION_NOT_ACTIVE",404);return json({ok:true,session_id:sid,status:"closed",next_action:"start_new_session"})}
async function professorStats(env){const [s,t,q,r,l,p,f]=await Promise.all([env.DB.prepare("SELECT COUNT(*) n FROM professor_sessions").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='question'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_lessons WHERE understanding_status='understood'").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_lessons WHERE understanding_status IN ('pending_retest','retry_required')").first(),env.DB.prepare("SELECT COUNT(*) n FROM professor_turns WHERE kind='retest' AND passed=0").first()]);return json({version:APP_VERSION,sessions:Number(s&&s.n)||0,turns:Number(t&&t.n)||0,questions:Number(q&&q.n)||0,retests:Number(r&&r.n)||0,validated_lessons:Number(l&&l.n)||0,understood_lessons:Number(l&&l.n)||0,pending_retests:Number(p&&p.n)||0,failed_retests:Number(f&&f.n)||0,criterion:"understood only after passed retest"})}
const PROFESSOR_PAGE='<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MELITURGOS — Professeur</title><style>body{margin:0;background:#0c0c0e;color:#eee;font:16px system-ui}main{max-width:900px;margin:auto;padding:24px 16px}section{background:#151518;border:1px solid #29292f;border-radius:16px;padding:16px;margin:12px 0}.grid{display:grid;gap:8px}textarea,input{width:100%;box-sizing:border-box;background:#101014;color:#fff;border:1px solid #3a3a42;border-radius:10px;padding:11px;margin:6px 0}button{background:#292932;color:#fff;border:1px solid #4a4a55;border-radius:10px;padding:10px;margin:4px;cursor:pointer}.answer,.meta{white-space:pre-wrap;background:#222227;padding:12px;border-radius:10px}.meta{background:transparent;color:#aaa;font-size:13px}</style></head><body><main><p><a href="/" style="color:#aaa">← MELITURGOS</a></p><h1>Mode Professeur / ChatGPT Work</h1><p class="meta">Session guidée sans accès aux secrets, Cloudflare ou déploiement.</p><section><button id="start-session">Démarrer une session</button><input id="session-goal" placeholder="Objectif"><div id="session-id" class="meta"></div></section><section class="grid" id="professor-media"><strong>Médias privés (R2)</strong><input id="professor-media-file" type="file" accept="image/jpeg,image/png,image/webp,audio/webm,audio/wav,audio/mpeg,video/webm,video/mp4"><button id="professor-media-upload" type="button">Envoyer le média</button><div id="professor-media-status" class="meta">Analyse indisponible ; sélectionnez un média après une question.</div></section><section class="grid"><textarea id="professor-question" placeholder="Question"></textarea><button id="send-question">Poser la question</button><div id="meliturgos-answer" class="answer"></div><div id="professor-evidence" class="meta"></div></section><section class="grid"><textarea id="professor-critique" placeholder="Critique"></textarea><textarea id="professor-correction" placeholder="Correction"></textarea><textarea id="improved-answer" placeholder="Meilleure réponse"></textarea><button id="send-correction">Envoyer la correction</button><button id="save-lesson">Valider comme leçon</button><textarea id="retest-question" placeholder="Question de retest"></textarea><label><input type="checkbox" id="retest-passed"> Compréhension validée</label><button id="retest">Nouvelle réponse / retest</button><button id="finish-session">Terminer la session</button><div id="professor-status" class="meta"></div></section><script>const q=s=>document.querySelector(s);let sid=null,tid=null;async function api(p,o){o=o||{};o.headers=Object.assign({"content-type":"application/json"},o.headers||{});const r=await fetch(p,o),t=await r.text();let j;try{j=JSON.parse(t)}catch{throw Error("Réponse non JSON")}if(!r.ok)throw Error(j.error||("HTTP "+r.status));return j}function fail(e){q("#professor-status").textContent="Erreur : "+e.message}q("#start-session").onclick=async()=>{try{const j=await api("/api/professor/session",{method:"POST",body:JSON.stringify({goal:q("#session-goal").value})});sid=j.session_id;q("#session-id").textContent="Session "+sid;window.dispatchEvent(new Event("professor-state"))}catch(e){fail(e)}};q("#send-question").onclick=async()=>{try{if(!sid)throw Error("Démarre une session");const j=await api("/api/professor/ask",{method:"POST",body:JSON.stringify({session_id:sid,question:q("#professor-question").value})});tid=j.turn_id;window.dispatchEvent(new Event("professor-state"));q("#meliturgos-answer").textContent=j.answer;q("#professor-evidence").textContent="Souvenirs : "+j.memories.length+"\\nConfiance : "+j.confidence+"\\nProvenance : "+(j.provenance||"professor_question")+"\\nSpécialiste : "+(j.specialist||"general_model")+"\\nOutils : "+Object.keys(j.tools).join(", ")}catch(e){fail(e)}};q("#send-correction").onclick=async()=>{try{await api("/api/professor/correct",{method:"POST",body:JSON.stringify({session_id:sid,turn_id:tid,critique:q("#professor-critique").value,correction:q("#professor-correction").value,improved_answer:q("#improved-answer").value})});q("#professor-status").textContent="Correction enregistrée"}catch(e){fail(e)}};q("#save-lesson").onclick=async()=>{try{const lesson=q("#professor-correction").value||q("#improved-answer").value;if(!sid||!tid||!lesson)throw Error("Correction et tour requis");const j=await api("/api/professor/lesson",{method:"POST",body:JSON.stringify({session_id:sid,turn_id:tid,lesson,rationale:q("#professor-critique").value})});q("#professor-status").textContent="Leçon validée, memory_id="+j.memory_id}catch(e){fail(e)}};q("#retest").onclick=async()=>{try{const j=await api("/api/professor/retest",{method:"POST",body:JSON.stringify({session_id:sid,question:q("#retest-question").value,passed:q("#retest-passed").checked})});tid=j.turn_id;q("#meliturgos-answer").textContent=j.answer;q("#professor-evidence").textContent="Retest · souvenirs : "+j.memories.length+" · leçons : "+j.lessons.length}catch(e){fail(e)}};q("#finish-session").onclick=async()=>{try{if(!sid)throw Error("Aucune session");q("#professor-status").textContent="Session persistée : "+sid;await api("/api/professor/close",{method:"POST",body:JSON.stringify({session_id:sid})})}catch(e){fail(e)}};q("#professor-media-upload").onclick=()=>{q("#professor-media-status").textContent="Téléversement désactivé : validation R2 requise.";};</script></main></body></html>';
async function professorPage(){const base=html(PROFESSOR_PAGE),body=await base.text(),panel='<section class="grid" id="capability-panel"><h2>Outils et modèles</h2><p class="meta">État réel des capacités. Une capacité indisponible n’est jamais présentée comme exécutée.</p><button id="refresh-capabilities" type="button">Actualiser les capacités</button><div id="capability-list" class="meta">Chargement…</div></section><script>(function(){var list=document.querySelector("#capability-list"),button=document.querySelector("#refresh-capabilities");async function refresh(){list.textContent="Chargement…";try{var registry=await api("/api/tools/registry"),lines=registry.tools.map(function(t){return (t.available?"✓":"○")+" "+t.name+" — "+t.effective_status+" — "+t.capability+"\\n  "+t.explanation});list.textContent=lines.join("\\n\\n")}catch(e){list.textContent="Registre indisponible : "+e.message}}button.onclick=refresh;refresh()})();</script>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithKnowledge=professorPage;professorPage=async function(){const base=await professorPageWithKnowledge(),body=await base.text(),panel='<section class="grid" id="knowledge-panel"><h2>Knowledge contrôlé</h2><p class="meta">Sources et imports restent privés, textuels et révocables. Aucune source n’est active sans autorisation explicite.</p><input id="knowledge-source-id" placeholder="ID source"><button id="knowledge-load" type="button">Charger source/import</button><button id="knowledge-revoke" type="button">Révoquer la source</button><div id="knowledge-state" class="meta">Aucune source chargée</div><script>(function(){var id=document.querySelector("#knowledge-source-id"),state=document.querySelector("#knowledge-state");document.querySelector("#knowledge-load").onclick=async function(){try{if(!id.value.trim())throw Error("ID source requis");var s=await api("/api/knowledge/source/"+encodeURIComponent(id.value.trim())),i=await api("/api/knowledge/import/"+encodeURIComponent(id.value.trim()));state.textContent="Source : "+s.source.name+" · statut "+s.source.status+" · confiance "+s.source.confidence+"\\nImports : "+(i.import?i.import.status:"introuvable")+" · erreurs : "+(i.import?i.import.error||"aucune":"-")}catch(e){state.textContent="Knowledge indisponible : "+e.message}};document.querySelector("#knowledge-revoke").onclick=async function(){try{if(!id.value.trim())throw Error("ID source requis");var r=await api("/api/knowledge/source/"+encodeURIComponent(id.value.trim())+"/revoke",{method:"POST",body:JSON.stringify({})});state.textContent="Source révoquée logiquement : "+r.status}catch(e){state.textContent="Révocation refusée : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithWorkflows=professorPage;professorPage=async function(){const base=await professorPageWithWorkflows(),body=await base.text(),panel='<section class="grid" id="workflow-improvements"><h2>Mesure et améliorations proposées</h2><p class="meta">Les variantes sont simulées uniquement et ne remplacent jamais le workflow stable.</p><button id="workflow-refresh" type="button">Mesurer les workflows</button><div id="workflow-results" class="meta">Aucune mesure chargée</div><script>(function(){var out=document.querySelector("#workflow-results");document.querySelector("#workflow-refresh").onclick=async function(){try{var s=await api("/api/tools/workflows/status"),v=await api("/api/tools/workflows/variant?workflow=professor&variant=detail-v1&simulation=true");out.textContent=JSON.stringify({mesures:s.workflows,proposition:v.proposal},null,2)}catch(e){out.textContent="Mesure indisponible : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
const professorPageWithSpecialists=professorPage;professorPage=async function(){const base=await professorPageWithSpecialists(),body=await base.text(),panel='<section class="grid" id="specialist-router"><h2>Spécialistes et routeur</h2><p class="meta">Profils séparés du modèle général ; tous désactivés jusqu’à validation.</p><button id="specialist-refresh" type="button">Afficher les spécialistes</button><div id="specialist-results" class="meta">Aucun spécialiste sélectionné</div><script>(function(){var out=document.querySelector("#specialist-results");document.querySelector("#specialist-refresh").onclick=async function(){try{var s=await api("/api/tools/specialists/status"),r=await api("/api/tools/specialists/select?q="+encodeURIComponent("Explique ce souvenir"));out.textContent=JSON.stringify({specialists:s.specialists,selection:r},null,2)}catch(e){out.textContent="Routeur indisponible : "+e.message}}})();</script></section>';return new Response(body.replace("</main>",panel+"</main>"),{status:base.status,headers:base.headers})}
