const ROOT_PAGE=`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#0c0c0e"><link rel="manifest" href="/manifest.webmanifest"><title>MELITURGOS</title><style>:root{color-scheme:dark;font-family:system-ui,-apple-system,sans-serif}*{box-sizing:border-box}body{margin:0;background:#0c0c0e;color:#f4f5f7}main{max-width:680px;margin:auto;padding:18px 14px 42px}header{display:flex;justify-content:space-between;gap:12px;align-items:start;margin-bottom:18px}h1{font-size:clamp(30px,8vw,44px);margin:0}p{color:#a8adb7}.status{font-size:12px;color:#a8adb7;text-align:right}.panel{background:#15171c;border:1px solid #2d333d;border-radius:18px;padding:14px;margin:12px 0}.chat{min-height:38vh;max-height:52vh;overflow:auto}.msg{white-space:pre-wrap;padding:11px 13px;border-radius:14px;margin:8px 0;line-height:1.5}.bot{background:#222933}.user{background:#1d3852;margin-left:8%}.meta{font-size:12px;color:#a8adb7}.actions{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.actions a,.actions button,button{min-height:46px;border:1px solid #566579;border-radius:12px;background:#223247;color:#fff;padding:11px;text-decoration:none;font:inherit;cursor:pointer}.composer{display:grid;grid-template-columns:1fr auto;gap:8px;position:sticky;bottom:8px}textarea,input,select{width:100%;background:#0f1115;color:#fff;border:1px solid #414a57;border-radius:12px;padding:11px;font:inherit}textarea{min-height:78px;resize:vertical}.voice{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media(max-width:440px){main{padding:12px 10px}.composer{grid-template-columns:1fr}.actions{grid-template-columns:1fr}.voice{grid-template-columns:1fr}}</style></head><body><main><header><div><h1>MELITURGOS</h1><p>Votre espace de conversation et de mémoire.</p></div><div id="status" class="status">Connexion…</div></header><section class="panel chat" id="chat" aria-live="polite"><div class="msg bot">Je suis prêt. Écrivez votre première question.</div></section><form class="panel composer" id="form"><textarea id="question" placeholder="Écrire un message…" aria-label="Message"></textarea><button type="submit">Envoyer</button></form><section class="panel voice"><button id="mic-start" type="button">🎙 Micro</button><button id="mic-stop" type="button" disabled>Arrêter</button><div id="voice-status" class="meta" style="grid-column:1/-1">Le micro reste inactif jusqu’à votre action.</div></section><section class="panel actions"><button id="memory" type="button">🧠 Mémoire</button><button id="diagnostic" type="button">◌ Diagnostic</button><button id="backup" type="button">↧ Sauvegarde</button></section><div id="info" class="meta" role="status"></div><script>(function(){var q=function(s){return document.querySelector(s)},chat=q('#chat'),input=q('#question'),info=q('#info'),rec,stream,parts=[];function add(t,c){var d=document.createElement('div');d.className='msg '+c;d.textContent=t;chat.appendChild(d);chat.scrollTop=chat.scrollHeight}async function api(path,o){var r=await fetch(path,o),j=await r.json();if(!r.ok)throw Error(j.error||('HTTP '+r.status));return j}var sending=false;q('#form').onsubmit=async function(e){e.preventDefault();if(sending)return;var t=input.value.trim();if(!t)return;sending=true;q('#form').querySelector('button[type=submit]').disabled=true;var provenance=input.dataset.provenance||'chat';input.value='';input.dataset.provenance='chat';add(t,'user');try{var j=await api('/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:t,provenance:input.dataset.provenance||"chat"})});add(j.text,'bot');if('speechSynthesis'in window){var u=new SpeechSynthesisUtterance(j.text);u.lang='fr-FR';u.voice=Array.from(speechSynthesis.getVoices()).find(function(v){return /fr/i.test(v.lang)&&/female|amelie|audrey|marie/i.test(v.name)})||null;speechSynthesis.speak(u)}}catch(e){add('Erreur : '+e.message,'bot')}finally{sending=false;q('#form').querySelector('button[type=submit]').disabled=false}};input.addEventListener('keydown',function(e){if(e.isComposing)return;if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();q('#form').requestSubmit()}});q('#memory').onclick=async function(){try{var j=await api('/api/status');info.textContent=j.memories+' souvenirs · '+j.interactions+' échanges'}catch(e){info.textContent='Mémoire indisponible'}};q('#diagnostic').onclick=async function(){info.textContent='Diagnostic…';try{var j=await api('/api/diagnostic');info.textContent='D1 '+j.checks.d1+' · AI '+(j.checks.ai_binding||j.checks.workers_ai&&j.checks.workers_ai.status)+' · '+j.latency_ms+' ms'}catch(e){info.textContent='Diagnostic indisponible'}};q('#backup').onclick=function(){location.href='/api/export'};q('#mic-start').onclick=async function(){if(!navigator.mediaDevices||!navigator.mediaDevices.getUserMedia){q('#voice-status').textContent='Micro indisponible · utilisez le texte';return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});parts=[];rec=new MediaRecorder(stream);rec.ondataavailable=function(e){if(e.data.size)parts.push(e.data)};rec.onstop=async function(){stream.getTracks().forEach(function(t){t.stop()});q('#voice-status').textContent='Transcription…';var fd=new FormData();fd.append('audio',new Blob(parts,{type:'audio/webm'}),'micro.webm');try{var r=await fetch('/api/voice/transcribe',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error||'indisponible');input.value=j.text;input.dataset.provenance='voice';q('#voice-status').textContent='Texte transcrit · envoyé à MEL';q('#form').requestSubmit()}catch(e){q('#voice-status').textContent='Transcription indisponible · repli texte'}};rec.start();q('#mic-start').disabled=true;q('#mic-stop').disabled=false;q('#voice-status').textContent='Écoute…'}catch(e){q('#voice-status').textContent='Micro refusé · repli texte'}};q('#mic-stop').onclick=function(){if(rec&&rec.state!=='inactive'){rec.stop();q('#mic-start').disabled=false;q('#mic-stop').disabled=true}};q('#memory').click()})()</script></main></body></html>`;

const ROOT_MEDIA_PANEL=`<section class="panel root-files" aria-labelledby="root-files-title"><h2 id="root-files-title">Fichiers</h2><p class="meta">Déposez un fichier ou sélectionnez-le. Aucun fichier inconnu n’est exécuté.</p><label id="root-drop" class="drop-zone" for="root-file"><strong>Déposer ici</strong><span>ou toucher pour sélectionner</span><input id="root-file" type="file" accept="*/*"></label><div id="root-file-info" class="meta" role="status" aria-live="polite">Aucun fichier sélectionné</div><button id="root-file-send" type="button" disabled>Envoyer vers R2 privé</button></section><section class="panel video-card" aria-labelledby="video-title"><h2 id="video-title">Assistant vidéo</h2><video id="root-video" controls playsinline muted hidden></video><div id="root-avatar" class="avatar-fallback" aria-label="Avatar animé de secours" role="img"><span>◉</span></div><p id="root-video-status" class="meta" role="status" aria-live="polite">Aperçu local uniquement. Analyse vidéo non disponible.</p><div class="video-actions"><button id="root-video-generate" type="button">Préparer une réponse vidéo</button><button id="root-video-speak" type="button">Lire la réponse</button></div></section>`;
const ROOT_MEDIA_SCRIPT=`<script>(function(){var q=function(s){return document.querySelector(s)},drop=q("#root-drop"),file=q("#root-file"),info=q("#root-file-info"),send=q("#root-file-send"),video=q("#root-video"),avatar=q("#root-avatar"),status=q("#root-video-status"),url=null,current=null;function ext(name){var i=name.lastIndexOf(".");return i>0?name.slice(i+1).toLowerCase():"(aucune)"}function describe(f,state){info.textContent=f?"Nom : "+f.name+" · extension : ."+ext(f.name)+" · type : "+(f.type||"application/octet-stream")+" · taille : "+f.size+" octets · état : "+state:"Aucun fichier sélectionné"}function clearUrl(){if(url){URL.revokeObjectURL(url);url=null}}function preview(f){clearUrl();current=f;describe(f,"prêt");send.disabled=false;if(f.type.indexOf("video/")===0){url=URL.createObjectURL(f);video.src=url;video.hidden=false;video.muted=true;avatar.hidden=true;status.textContent="Aperçu vidéo local · analyse non disponible"}else{video.removeAttribute("src");video.load();video.hidden=true;avatar.hidden=false;status.textContent="Format non vidéo · analyse non disponible"}}file.onchange=function(){if(file.files[0])preview(file.files[0])};["dragenter","dragover"].forEach(function(e){drop.addEventListener(e,function(x){x.preventDefault();drop.classList.add("dragging")})});["dragleave","drop"].forEach(function(e){drop.addEventListener(e,function(x){x.preventDefault();drop.classList.remove("dragging")})});drop.addEventListener("drop",function(e){var f=e.dataTransfer.files&&e.dataTransfer.files[0];if(f)preview(f)});send.onclick=async function(){if(!current)return;send.disabled=true;describe(current,"envoi…");var fd=new FormData();fd.append("file",current,current.name);try{var r=await fetch("/api/media/root-upload",{method:"POST",body:fd}),j=await r.json();if(!r.ok)throw Error(j.error||("HTTP "+r.status));describe(current,"envoyé · R2 privé");status.textContent=j.analysis_supported?"analyse non disponible":"analyse non disponible pour ce format"}catch(e){describe(current,"échec");status.textContent=e.message}finally{send.disabled=false}};q("#root-video-generate").onclick=async function(){status.textContent="Vérification de la route avatar vidéo…";try{var r=await fetch("/api/avatar/video",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({text:"Réponse MELITURGOS"})}),j=await r.json();if(j.video_url||j.url){var candidate=new URL(j.video_url||j.url,location.origin);if(candidate.origin!==location.origin)throw Error("URL vidéo externe refusée");video.src=candidate.href;video.hidden=false;video.muted=true;avatar.hidden=true;status.textContent="Vidéo fournie par la route authentifiée"}else if(j.code==="AVATAR_PROVIDER_NOT_CONFIGURED"){throw Error("AVATAR_PROVIDER_NOT_CONFIGURED")}else throw Error("Aucune vidéo générée") }catch(e){video.removeAttribute("src");video.hidden=true;avatar.hidden=false;avatar.classList.remove("speaking");void avatar.offsetWidth;avatar.classList.add("speaking");status.textContent="AVATAR_PROVIDER_NOT_CONFIGURED · avatar animé de secours · synthèse vocale navigateur";if("speechSynthesis"in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance("Réponse vidéo indisponible. Utilisez la conversation texte."))}}};q("#root-video-speak").onclick=async function(){var text=(q("#question")&&q("#question").value)||"Réponse MELITURGOS";try{var r=await fetch("/api/voice/speak",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({text:text})});if(!r.ok)throw Error("voix indisponible");var a=new Audio(URL.createObjectURL(await r.blob()));await a.play()}catch(e){if("speechSynthesis"in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(text))}status.textContent="Lecture vocale navigateur"}}})();</script>`;
const ROOT_PAGE_PATCHED=ROOT_PAGE.replace("</style></head>",".root-files,.video-card{margin-top:12px}.mel-assistant{display:flex;align-items:center;gap:12px}.mel-avatar{width:84px;height:84px;max-width:84px;max-height:84px;flex:0 0 84px;overflow:hidden;text-align:center;font-weight:700;border-radius:50%}.mel-avatar img{display:block;width:100%;height:100%;max-width:100%;max-height:100%;object-fit:cover;border-radius:50%;margin:auto}.mel-avatar.speaking img{animation:mel-speaking 700ms ease-in-out infinite alternate}@keyframes mel-speaking{to{transform:scale(1.06);filter:brightness(1.2)}}.drop-zone{display:grid;gap:6px;place-items:center;border:2px dashed #60758b;border-radius:16px;padding:22px 12px;text-align:center;cursor:pointer;background:#101820}.drop-zone.dragging{border-color:#8fd3ff;background:#19324a}.drop-zone input{position:absolute;width:1px;height:1px;opacity:0}.root-files button,.video-actions button{width:100%;margin-top:10px}.video-card video{width:100%;max-height:220px;border-radius:12px;background:#07090d}.avatar-fallback{display:grid;place-items:center;width:100%;height:120px;border-radius:12px;background:linear-gradient(135deg,#19324a,#0d141d);font-size:48px}.avatar-fallback.speaking{animation:avatar-pulse 900ms ease-in-out infinite alternate}@keyframes avatar-pulse{to{transform:scale(1.03);filter:brightness(1.35)}}.video-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media(max-width:440px){.video-actions{grid-template-columns:1fr}}</style></head>").replace("</main></body>",ROOT_MEDIA_PANEL+"</main>"+ROOT_MEDIA_SCRIPT+"</body>");

const ROOT_ANALYSIS_PANEL=`<section class="panel root-files" aria-labelledby="file-title"><h2 id="file-title">Analyse de fichier</h2><label id="root-drop" class="drop-zone">Déposer ici ou sélectionner un fichier<input id="root-file" type="file" accept="*/*"></label><div id="root-file-info" class="meta">Aucun fichier sélectionné</div><div id="root-file-preview"></div><div id="root-file-analysis" class="analysis-result" aria-live="polite"></div><button id="root-file-send" disabled>Envoyer vers R2 privé</button></section>`;
const ROOT_ANALYSIS_SCRIPT=`<script>(function(){var q=function(s){return document.querySelector(s)},drop=q('#root-drop'),input=q('#root-file'),info=q('#root-file-info'),preview=q('#root-file-preview'),result=q('#root-file-analysis'),send=q('#root-file-send'),video=q('#root-video'),avatar=q('#root-avatar'),vstatus=q('#root-video-status'),current=null,localUrl=null;function ext(n){var i=n.lastIndexOf('.');return i>0?n.slice(i+1).toLowerCase():'(aucune)'}function desc(f,state){info.textContent=f?'Nom : '+f.name+' · extension : .'+ext(f.name)+' · type : '+(f.type||'application/octet-stream')+' · taille : '+f.size+' octets · état : '+state:'Aucun fichier sélectionné'}function clearUrl(){if(localUrl){URL.revokeObjectURL(localUrl);localUrl=null}}function showPreview(f){clearUrl();preview.textContent='';if(!f)return;localUrl=URL.createObjectURL(f);if(f.type.indexOf('video/')===0){var v=document.createElement('video');v.controls=true;v.playsInline=true;v.muted=true;v.src=localUrl;preview.appendChild(v)}else if(f.type.indexOf('image/')===0){var im=document.createElement('img');im.alt='Aperçu local';im.src=localUrl;preview.appendChild(im)}else if(f.type.indexOf('audio/')===0){var a=document.createElement('audio');a.controls=true;a.src=localUrl;preview.appendChild(a)}}async function analyze(f){desc(f,'analyse…');result.textContent='';var fd=new FormData();fd.append('file',f,f.name);try{var r=await fetch('/api/files/analyze',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error||('HTTP '+r.status));desc(f,j.status);var lines=[j.message||'',j.summary||'',j.analysis||'',j.transcription?'Transcription : '+j.transcription:'',j.preview_text?'Aperçu texte : '+j.preview_text.slice(0,1600):''].filter(Boolean);result.textContent=lines.join('\n\n')}catch(e){desc(f,'échec');result.textContent=e.message}finally{send.disabled=false}}function select(f){current=f;desc(f,'prêt');showPreview(f);send.disabled=true;analyze(f)}input.onchange=function(){if(input.files[0])select(input.files[0])};['dragenter','dragover'].forEach(function(e){drop.addEventListener(e,function(x){x.preventDefault();drop.classList.add('dragging')})});['dragleave','drop'].forEach(function(e){drop.addEventListener(e,function(x){x.preventDefault();drop.classList.remove('dragging')})});drop.addEventListener('drop',function(e){var f=e.dataTransfer.files&&e.dataTransfer.files[0];if(f)select(f)});send.onclick=async function(){if(!current)return;send.disabled=true;desc(current,'envoi…');var fd=new FormData();fd.append('file',current,current.name);try{var r=await fetch('/api/media/root-upload',{method:'POST',body:fd}),j=await r.json();if(!r.ok)throw Error(j.error||('HTTP '+r.status));desc(current,'envoyé · R2 privé');result.textContent='Stockage privé R2 confirmé. '+(j.message||'analyse non disponible')}catch(e){desc(current,'échec');result.textContent=e.message}finally{send.disabled=false}}})();</script>`;
const ROOT_VOICE_PANEL='<section class="panel voice"><button id="mic-start" type="button">🎙 Micro</button><button id="mic-stop" type="button" disabled>Arrêter</button><div id="voice-status" class="meta" style="grid-column:1/-1">Le micro reste inactif jusqu’à votre action.</div></section>';
const ROOT_PAGE_INTERFACE=ROOT_PAGE.replace(/<section class="panel actions"><button id="memory"[\s\S]*?<\/section>/,'').replace(/<section class="panel voice">[\s\S]*?<\/section>/,'').replace("+j.interactions+' échanges", "").replace("+s.interactions+' échanges", "");
const ROOT_PAGE_PATCHED_V2=ROOT_PAGE_INTERFACE.replace('</style></head>','.root-files,.video-card{margin-top:12px}.drop-zone{display:grid;gap:6px;place-items:center;border:2px dashed #60758b;border-radius:16px;padding:22px 12px;text-align:center;cursor:pointer;background:#101820}.drop-zone.dragging{border-color:#8fd3ff;background:#19324a}.drop-zone input{position:absolute;width:1px;height:1px;opacity:0}.root-files button,.video-actions button{width:100%;margin-top:10px}.video-card video,.file-preview video,.file-preview img,.file-preview audio{width:100%;max-height:220px;border-radius:12px;background:#07090d}.analysis-result{white-space:pre-wrap;margin-top:10px;line-height:1.45}.avatar-fallback{display:grid;place-items:center;width:100%;height:120px;border-radius:12px;background:linear-gradient(135deg,#19324a,#0d141d);font-size:48px}.avatar-fallback.speaking{animation:avatar-pulse 900ms ease-in-out infinite alternate}@keyframes avatar-pulse{to{transform:scale(1.03);filter:brightness(1.35)}}.video-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}@media(max-width:440px){.video-actions{grid-template-columns:1fr}}</style></head>').replace('</main></body>',ROOT_ANALYSIS_PANEL+ROOT_VOICE_PANEL+'</main>'+ROOT_ANALYSIS_SCRIPT+'</body>');
const ROOT_ASSISTANT=`<section class="panel mel-assistant" aria-label="Avatar MEL"><div class="mel-avatar" aria-hidden="true"><img src="/meliturgos-avatar-fille.png" alt="" onerror="this.hidden=true"></div></section>`;
const ROOT_VOICE_ENHANCEMENT=`<script>(function(){var activationPhrases=['Bonjour MEL','Allô MEL','Allo MEL'],s=document.querySelector('#mel-state'),start=document.querySelector('#mic-start'),stop=document.querySelector('#mic-stop'),input=document.querySelector('#question'),form=document.querySelector('#form'),voice=document.querySelector('#voice-status'),SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!s)return;function set(t){s.textContent=t;if(voice)voice.textContent=t}var av=document.querySelector('.mel-avatar');if(av&&'speechSynthesis'in window){var speak=window.speechSynthesis.speak.bind(window.speechSynthesis);window.speechSynthesis.speak=function(u){av.classList.add('speaking');u.onend=function(){av.classList.remove('speaking')};u.onerror=function(){av.classList.remove('speaking')};speak(u)}}if(start){var original=start.onclick;start.onclick=async function(){set('Veille · dites Bonjour MEL');if(SR){var wake=new SR();wake.lang='fr-FR';wake.continuous=true;wake.interimResults=false;wake.onresult=function(e){for(var i=e.resultIndex;i<e.results.length;i++){var t=e.results[i][0].transcript.normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();if(/bonjour mel|allo mel/.test(t)){wake.stop();set('MEL écoute');if(original)original.call(start);break}}};wake.onerror=function(){set('Micro prêt · activation manuelle')};wake.start()}else if(original)original.call(start)}}})();</script>`;
const ROOT_BOTTOM_ACTIONS=`<section class="panel actions secondary-actions" aria-label="Actions secondaires"><button type="button" id="new-session">Nouvelle session</button><button type="button" id="ask-focus">Poser une question</button><button type="button" id="memory">🧠 Mémoire</button><button type="button" id="diagnostic">◌ Diagnostic</button><button type="button" id="backup">↧ Sauvegarde</button><button type="button" id="attach-image">Joindre une image</button><button type="button" id="attach-audio">Joindre un audio</button><button type="button" id="attach-video">Joindre une vidéo</button><button type="button" id="root-correct" disabled title="Disponible dans /professor avec une session active">Corriger</button><button type="button" id="root-lesson" disabled title="Disponible dans /professor avec un tour actif">Transformer en leçon</button><button type="button" id="root-retest" disabled title="Disponible dans /professor avec une session active">Retester</button><a href="/professor">Accéder au mode professeur</a><button type="button" id="show-modules">Afficher les modules</button></section><details class="panel" id="autonomy"><summary>Autonomie développeur</summary><div id="autonomy-state">proposition · autorisation requise</div><div id="module-list" class="meta">Registre en attente</div><p class="meta">Les écritures et déploiements restent soumis à autorisation du runner local.</p></details><section class="panel root-video-module" aria-labelledby="root-video-title"><h2 id="root-video-title">Module vidéo</h2><p class="meta">Aperçu local uniquement. Aucune synchronisation labiale.</p><input id="root-avatar-video" type="file" accept="video/*"><video id="root-avatar-video-preview" controls playsinline hidden></video><div id="root-avatar-video-status" class="meta" role="status">Aucune vidéo sélectionnée</div></section>`;
const ROOT_CAPABILITIES=`<script>(function(){var el=document.querySelector('#capabilities');if(!el)return;fetch('/api/status').then(function(r){return r.json()}).then(function(s){var c=s.checks||{},labels=['conversation texte : '+(c.workers_ai&&c.workers_ai.status!=='missing'?'disponible':'indisponible'), 'mémoire D1 : '+(c.d1==='ok'?'disponible':'erreur de configuration'),'transcription audio : '+(c.workers_ai?'disponible':'indisponible'),'synthèse vocale : '+(c.workers_ai?'disponible':'indisponible'),'dépôt R2 : '+(c.media_bucket&&c.media_bucket.status!=='missing'?'disponible':'indisponible'),'analyse d’image : indisponible','analyse audio : '+(c.workers_ai?'disponible':'indisponible'),'analyse vidéo : indisponible','connecteurs externes : désactivé','mode professeur : disponible'];el.textContent=labels.join(' · ')}).catch(function(){el.textContent='Capacités : erreur de configuration'});var btn=document.querySelector('#show-modules');if(btn)btn.onclick=function(){fetch('/api/modules/registry').then(function(r){return r.json()}).then(function(j){document.querySelector('#module-list').textContent=(j.modules||[]).map(function(m){return m.name+' : '+m.state}).join(' · ')})}})();</script>`;
